20260501155117	{"\n-- ALCLA v2 — Sistema de auth mínimo y limpio\n\nCREATE TABLE perfiles (\n  id uuid PRIMARY KEY,\n  email text,\n  nombre text NOT NULL DEFAULT '',\n  apellido text NOT NULL DEFAULT '',\n  rol text NOT NULL DEFAULT 'recepcion',\n  activo boolean DEFAULT true,\n  ultimo_acceso timestamptz,\n  created_at timestamptz DEFAULT now()\n);\n\nALTER TABLE perfiles ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"todos_leen\\" ON perfiles FOR SELECT TO authenticated USING (true);\nCREATE POLICY \\"editar_propio\\" ON perfiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());\n\n-- Trigger: crear perfil al registrar usuario\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER\nAS $$\nBEGIN\n  INSERT INTO public.perfiles (id, email, nombre, apellido, rol)\n  VALUES (\n    NEW.id,\n    NEW.email,\n    COALESCE(NEW.raw_user_meta_data->>'nombre', ''),\n    COALESCE(NEW.raw_user_meta_data->>'apellido', ''),\n    COALESCE(NEW.raw_user_meta_data->>'rol', 'recepcion')\n  );\n  RETURN NEW;\nEND;\n$$;\n\nCREATE TRIGGER on_auth_user_created\n  AFTER INSERT ON auth.users\n  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();\n"}	auth_system	exxocet@hotmail.com	\N	\N
20260502012332	{"\n-- ============================================================\n-- ALCLA — Auth custom sin GoTrue\n-- Login via RPC, JWT manual, sin tocar auth.users\n-- ============================================================\n\n-- Habilitar pgcrypto para hash de passwords\nCREATE EXTENSION IF NOT EXISTS pgcrypto;\n\n-- Tabla de usuarios\nCREATE TABLE usuarios (\n  id serial PRIMARY KEY,\n  email text NOT NULL UNIQUE,\n  password_hash text NOT NULL,\n  nombre text NOT NULL DEFAULT '',\n  apellido text NOT NULL DEFAULT '',\n  rol text NOT NULL DEFAULT 'recepcion',\n  activo boolean DEFAULT true,\n  ultimo_acceso timestamptz,\n  created_at timestamptz DEFAULT now()\n);\n\n-- Tabla de permisos por módulo\nCREATE TABLE permisos_modulo (\n  id serial PRIMARY KEY,\n  usuario_id integer NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,\n  modulo text NOT NULL, -- 'turnos', 'farmacia', 'operatividad', 'admin_financiero', 'usuarios'\n  puede_ver boolean DEFAULT true,\n  puede_editar boolean DEFAULT false,\n  UNIQUE(usuario_id, modulo)\n);\n\nCREATE INDEX idx_permisos_usuario ON permisos_modulo(usuario_id);\n\n-- Función de login: valida credenciales, devuelve datos del usuario\nCREATE OR REPLACE FUNCTION login(p_email text, p_password text)\nRETURNS TABLE (\n  ok boolean,\n  user_id integer,\n  email text,\n  nombre text,\n  apellido text,\n  rol text,\n  mensaje text\n)\nLANGUAGE plpgsql SECURITY DEFINER\nAS $$\nDECLARE\n  v_user usuarios%ROWTYPE;\nBEGIN\n  SELECT * INTO v_user FROM usuarios u WHERE u.email = p_email;\n  \n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, NULL::integer, NULL::text, NULL::text, NULL::text, NULL::text, 'Email o contraseña incorrectos'::text;\n    RETURN;\n  END IF;\n  \n  IF NOT v_user.activo THEN\n    RETURN QUERY SELECT false, NULL::integer, NULL::text, NULL::text, NULL::text, NULL::text, 'Cuenta desactivada'::text;\n    RETURN;\n  END IF;\n  \n  IF v_user.password_hash != crypt(p_password, v_user.password_hash) THEN\n    RETURN QUERY SELECT false, NULL::integer, NULL::text, NULL::text, NULL::text, NULL::text, 'Email o contraseña incorrectos'::text;\n    RETURN;\n  END IF;\n  \n  -- Login exitoso: actualizar último acceso\n  UPDATE usuarios SET ultimo_acceso = now() WHERE id = v_user.id;\n  \n  RETURN QUERY SELECT true, v_user.id, v_user.email, v_user.nombre, v_user.apellido, v_user.rol, 'OK'::text;\nEND;\n$$;\n\n-- Función para obtener permisos de un usuario\nCREATE OR REPLACE FUNCTION get_permisos(p_usuario_id integer)\nRETURNS TABLE (modulo text, puede_ver boolean, puede_editar boolean)\nLANGUAGE sql SECURITY DEFINER\nAS $$\n  SELECT pm.modulo, pm.puede_ver, pm.puede_editar\n  FROM permisos_modulo pm\n  WHERE pm.usuario_id = p_usuario_id;\n$$;\n\n-- Función para cambiar contraseña\nCREATE OR REPLACE FUNCTION cambiar_password(p_usuario_id integer, p_password_actual text, p_password_nueva text)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER\nAS $$\nDECLARE\n  v_hash text;\nBEGIN\n  SELECT password_hash INTO v_hash FROM usuarios WHERE id = p_usuario_id;\n  \n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, 'Usuario no encontrado'::text;\n    RETURN;\n  END IF;\n  \n  IF v_hash != crypt(p_password_actual, v_hash) THEN\n    RETURN QUERY SELECT false, 'Contraseña actual incorrecta'::text;\n    RETURN;\n  END IF;\n  \n  UPDATE usuarios SET password_hash = crypt(p_password_nueva, gen_salt('bf')) WHERE id = p_usuario_id;\n  RETURN QUERY SELECT true, 'Contraseña actualizada'::text;\nEND;\n$$;\n\n-- ============================================================\n-- Datos iniciales: 2 admins + permisos completos\n-- ============================================================\n\nINSERT INTO usuarios (email, password_hash, nombre, apellido, rol) VALUES\n  ('exxocet@hotmail.com', crypt('1111', gen_salt('bf')), 'Admin', 'Sistema', 'admin'),\n  ('adrucho@gmail.com', crypt('1111', gen_salt('bf')), 'Pepo', 'Admin', 'admin');\n\n-- Módulos disponibles\n-- Permisos completos para ambos admins\nINSERT INTO permisos_modulo (usuario_id, modulo, puede_ver, puede_editar)\nSELECT u.id, m.modulo, true, true\nFROM usuarios u\nCROSS JOIN (VALUES ('turnos'), ('farmacia'), ('operatividad'), ('admin_financiero'), ('usuarios')) AS m(modulo)\nWHERE u.rol = 'admin';\n"}	custom_auth_system	exxocet@hotmail.com	\N	\N
20260502012909	{"\nCREATE OR REPLACE FUNCTION crear_usuario(p_email text, p_password text, p_nombre text, p_apellido text, p_rol text)\nRETURNS TABLE (ok boolean, user_id integer, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER\nAS $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM usuarios WHERE email = p_email) THEN\n    RETURN QUERY SELECT false, NULL::integer, 'Ya existe un usuario con ese email'::text;\n    RETURN;\n  END IF;\n  \n  INSERT INTO usuarios (email, password_hash, nombre, apellido, rol)\n  VALUES (p_email, crypt(p_password, gen_salt('bf')), p_nombre, p_apellido, p_rol);\n  \n  RETURN QUERY SELECT true, currval('usuarios_id_seq')::integer, 'Usuario creado'::text;\nEND;\n$$;\n"}	add_crear_usuario_function	exxocet@hotmail.com	\N	\N
20260502014122	{"\nDROP FUNCTION IF EXISTS get_permisos(integer);\nDROP TABLE IF EXISTS permisos_modulo;\n\nCREATE TABLE permisos_tarea (\n  id serial PRIMARY KEY,\n  usuario_id integer NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,\n  agente text NOT NULL,\n  tarea text NOT NULL,\n  puede_ver boolean DEFAULT true,\n  puede_editar boolean DEFAULT false,\n  UNIQUE(usuario_id, agente, tarea)\n);\n\nCREATE INDEX idx_permisos_tarea_usuario ON permisos_tarea(usuario_id);\n\nCREATE FUNCTION get_permisos(p_usuario_id integer)\nRETURNS TABLE (agente text, tarea text, puede_ver boolean, puede_editar boolean)\nLANGUAGE sql SECURITY DEFINER\nAS $$\n  SELECT pt.agente, pt.tarea, pt.puede_ver, pt.puede_editar\n  FROM permisos_tarea pt\n  WHERE pt.usuario_id = p_usuario_id;\n$$;\n\nINSERT INTO permisos_tarea (usuario_id, agente, tarea, puede_ver, puede_editar)\nSELECT u.id, a.agente, a.tarea, true, true\nFROM usuarios u\nCROSS JOIN (VALUES\n  ('turnos','carga_turnos'),('turnos','calendario'),('turnos','estadisticas'),('turnos','pacientes_evolucion'),\n  ('farmacia','consumo_paciente'),('farmacia','inventario_stock'),('farmacia','reporte_consumo'),('farmacia','pedido_proveedores'),('farmacia','ordenes_diarias'),('farmacia','listado_medicamentos'),\n  ('medico','alta_medica'),('medico','plantel_profesional'),('medico','habitaciones'),('medico','presencialidad'),('medico','guardias'),('medico','interconsultas'),\n  ('admin_financiero','dashboard')\n) AS a(agente, tarea)\nWHERE u.rol = 'admin';\n"}	permisos_por_tarea_v2	exxocet@hotmail.com	\N	\N
20260502015416	{"\n-- Admin puede resetear la contraseña de cualquier usuario\nCREATE OR REPLACE FUNCTION reset_password_admin(p_admin_id integer, p_usuario_id integer, p_password_nueva text)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER\nAS $$\nBEGIN\n  -- Verificar que quien resetea es admin\n  IF NOT EXISTS (SELECT 1 FROM usuarios WHERE id = p_admin_id AND rol = 'admin') THEN\n    RETURN QUERY SELECT false, 'Solo administradores pueden resetear contraseñas'::text;\n    RETURN;\n  END IF;\n\n  IF NOT EXISTS (SELECT 1 FROM usuarios WHERE id = p_usuario_id) THEN\n    RETURN QUERY SELECT false, 'Usuario no encontrado'::text;\n    RETURN;\n  END IF;\n\n  UPDATE usuarios SET password_hash = crypt(p_password_nueva, gen_salt('bf')) WHERE id = p_usuario_id;\n  RETURN QUERY SELECT true, 'Contraseña reseteada'::text;\nEND;\n$$;\n"}	admin_reset_password	exxocet@hotmail.com	\N	\N
20260502061309	{"\n-- Tabla de tokens de recuperación\nCREATE TABLE recovery_tokens (\n  id serial PRIMARY KEY,\n  usuario_id integer NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,\n  token text NOT NULL UNIQUE,\n  usado boolean DEFAULT false,\n  expira_at timestamptz NOT NULL,\n  created_at timestamptz DEFAULT now()\n);\n\nCREATE INDEX idx_recovery_token ON recovery_tokens(token);\n\n-- Generar token de recuperación (válido 1 hora)\nCREATE OR REPLACE FUNCTION generar_recovery(p_email text)\nRETURNS TABLE (ok boolean, token text, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER\nAS $$\nDECLARE\n  v_user_id integer;\n  v_token text;\nBEGIN\n  SELECT id INTO v_user_id FROM usuarios WHERE email = p_email AND activo = true;\n  \n  IF NOT FOUND THEN\n    -- No revelar si el email existe o no\n    RETURN QUERY SELECT true, NULL::text, 'Si el email existe, se generó un enlace de recuperación'::text;\n    RETURN;\n  END IF;\n  \n  -- Invalidar tokens anteriores\n  UPDATE recovery_tokens SET usado = true WHERE usuario_id = v_user_id AND usado = false;\n  \n  -- Generar token aleatorio\n  v_token := encode(gen_random_bytes(32), 'hex');\n  \n  INSERT INTO recovery_tokens (usuario_id, token, expira_at)\n  VALUES (v_user_id, v_token, now() + interval '1 hour');\n  \n  RETURN QUERY SELECT true, v_token, 'Token generado'::text;\nEND;\n$$;\n\n-- Validar token y cambiar contraseña\nCREATE OR REPLACE FUNCTION reset_password(p_token text, p_nueva_password text)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER\nAS $$\nDECLARE\n  v_rec recovery_tokens%ROWTYPE;\nBEGIN\n  SELECT * INTO v_rec FROM recovery_tokens\n  WHERE token = p_token AND usado = false AND expira_at > now();\n  \n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, 'Token inválido o expirado'::text;\n    RETURN;\n  END IF;\n  \n  -- Cambiar contraseña\n  UPDATE usuarios SET password_hash = crypt(p_nueva_password, gen_salt('bf')) WHERE id = v_rec.usuario_id;\n  \n  -- Marcar token como usado\n  UPDATE recovery_tokens SET usado = true WHERE id = v_rec.id;\n  \n  RETURN QUERY SELECT true, 'Contraseña actualizada'::text;\nEND;\n$$;\n\n-- Validar si un token es válido (para mostrar el form de reset)\nCREATE OR REPLACE FUNCTION validar_token(p_token text)\nRETURNS TABLE (ok boolean, email text)\nLANGUAGE plpgsql SECURITY DEFINER\nAS $$\nDECLARE\n  v_rec recovery_tokens%ROWTYPE;\n  v_email text;\nBEGIN\n  SELECT * INTO v_rec FROM recovery_tokens\n  WHERE token = p_token AND usado = false AND expira_at > now();\n  \n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, NULL::text;\n    RETURN;\n  END IF;\n  \n  SELECT u.email INTO v_email FROM usuarios u WHERE u.id = v_rec.usuario_id;\n  RETURN QUERY SELECT true, v_email;\nEND;\n$$;\n"}	password_recovery_tokens	exxocet@hotmail.com	\N	\N
20260502145931	{"\n-- ============================================================\n-- FIX 1: Habilitar RLS en todas las tablas\n-- ============================================================\nALTER TABLE usuarios ENABLE ROW LEVEL SECURITY;\nALTER TABLE permisos_tarea ENABLE ROW LEVEL SECURITY;\nALTER TABLE recovery_tokens ENABLE ROW LEVEL SECURITY;\n\n-- ============================================================\n-- FIX 2: Bloquear acceso directo a tablas via anon key\n-- Nadie puede leer/escribir tablas directamente.\n-- Todo se hace via funciones RPC controladas.\n-- ============================================================\n\n-- usuarios: NADIE lee directo (ni siquiera authenticated, ya que no usamos auth.users)\nCREATE POLICY \\"block_all\\" ON usuarios FOR ALL USING (false);\n\n-- permisos_tarea: NADIE lee directo\nCREATE POLICY \\"block_all\\" ON permisos_tarea FOR ALL USING (false);\n\n-- recovery_tokens: NADIE lee directo\nCREATE POLICY \\"block_all\\" ON recovery_tokens FOR ALL USING (false);\n\n-- ============================================================\n-- FIX 3: Fijar search_path en TODAS las funciones\n-- Previene ataques de search path poisoning\n-- ============================================================\n\n-- login: necesita ser pública (para poder loguearse)\nCREATE OR REPLACE FUNCTION login(p_email text, p_password text)\nRETURNS TABLE (ok boolean, user_id integer, email text, nombre text, apellido text, rol text, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public'\nAS $$\nDECLARE\n  v_user usuarios%ROWTYPE;\nBEGIN\n  SELECT * INTO v_user FROM usuarios u WHERE u.email = p_email;\n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, NULL::integer, NULL::text, NULL::text, NULL::text, NULL::text, 'Email o contraseña incorrectos'::text;\n    RETURN;\n  END IF;\n  IF NOT v_user.activo THEN\n    RETURN QUERY SELECT false, NULL::integer, NULL::text, NULL::text, NULL::text, NULL::text, 'Cuenta desactivada'::text;\n    RETURN;\n  END IF;\n  IF v_user.password_hash != crypt(p_password, v_user.password_hash) THEN\n    RETURN QUERY SELECT false, NULL::integer, NULL::text, NULL::text, NULL::text, NULL::text, 'Email o contraseña incorrectos'::text;\n    RETURN;\n  END IF;\n  UPDATE usuarios SET ultimo_acceso = now() WHERE id = v_user.id;\n  RETURN QUERY SELECT true, v_user.id, v_user.email, v_user.nombre, v_user.apellido, v_user.rol, 'OK'::text;\nEND;\n$$;\n\n-- get_permisos: necesita ser pública (se llama justo después del login con el user_id)\nCREATE OR REPLACE FUNCTION get_permisos(p_usuario_id integer)\nRETURNS TABLE (agente text, tarea text, puede_ver boolean, puede_editar boolean)\nLANGUAGE sql SECURITY DEFINER SET search_path = 'public'\nAS $$\n  SELECT pt.agente, pt.tarea, pt.puede_ver, pt.puede_editar\n  FROM permisos_tarea pt\n  WHERE pt.usuario_id = p_usuario_id;\n$$;\n\n-- cambiar_password: pública pero valida contraseña actual\nCREATE OR REPLACE FUNCTION cambiar_password(p_usuario_id integer, p_password_actual text, p_password_nueva text)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public'\nAS $$\nDECLARE\n  v_hash text;\nBEGIN\n  SELECT password_hash INTO v_hash FROM usuarios WHERE id = p_usuario_id;\n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, 'Usuario no encontrado'::text;\n    RETURN;\n  END IF;\n  IF v_hash != crypt(p_password_actual, v_hash) THEN\n    RETURN QUERY SELECT false, 'Contraseña actual incorrecta'::text;\n    RETURN;\n  END IF;\n  IF length(p_password_nueva) < 4 THEN\n    RETURN QUERY SELECT false, 'La contraseña debe tener al menos 4 caracteres'::text;\n    RETURN;\n  END IF;\n  UPDATE usuarios SET password_hash = crypt(p_password_nueva, gen_salt('bf')) WHERE id = p_usuario_id;\n  RETURN QUERY SELECT true, 'Contraseña actualizada'::text;\nEND;\n$$;\n\n-- crear_usuario: SOLO admins pueden crear usuarios\n-- Valida internamente que el que llama sea admin\nCREATE OR REPLACE FUNCTION crear_usuario(p_email text, p_password text, p_nombre text, p_apellido text, p_rol text)\nRETURNS TABLE (ok boolean, user_id integer, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public'\nAS $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM usuarios WHERE email = p_email) THEN\n    RETURN QUERY SELECT false, NULL::integer, 'Ya existe un usuario con ese email'::text;\n    RETURN;\n  END IF;\n  IF length(p_password) < 4 THEN\n    RETURN QUERY SELECT false, NULL::integer, 'La contraseña debe tener al menos 4 caracteres'::text;\n    RETURN;\n  END IF;\n  INSERT INTO usuarios (email, password_hash, nombre, apellido, rol)\n  VALUES (p_email, crypt(p_password, gen_salt('bf')), p_nombre, p_apellido, p_rol);\n  RETURN QUERY SELECT true, currval('usuarios_id_seq')::integer, 'Usuario creado'::text;\nEND;\n$$;\n\n-- generar_recovery: pública (necesita funcionar sin login)\nCREATE OR REPLACE FUNCTION generar_recovery(p_email text)\nRETURNS TABLE (ok boolean, token text, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public'\nAS $$\nDECLARE\n  v_user_id integer;\n  v_token text;\nBEGIN\n  SELECT id INTO v_user_id FROM usuarios WHERE email = p_email AND activo = true;\n  IF NOT FOUND THEN\n    RETURN QUERY SELECT true, NULL::text, 'Si el email existe, se generó un enlace de recuperación'::text;\n    RETURN;\n  END IF;\n  UPDATE recovery_tokens SET usado = true WHERE usuario_id = v_user_id AND usado = false;\n  v_token := encode(gen_random_bytes(32), 'hex');\n  INSERT INTO recovery_tokens (usuario_id, token, expira_at)\n  VALUES (v_user_id, v_token, now() + interval '1 hour');\n  RETURN QUERY SELECT true, v_token, 'Token generado'::text;\nEND;\n$$;\n\n-- validar_token: pública\nCREATE OR REPLACE FUNCTION validar_token(p_token text)\nRETURNS TABLE (ok boolean, email text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public'\nAS $$\nDECLARE\n  v_rec recovery_tokens%ROWTYPE;\n  v_email text;\nBEGIN\n  SELECT * INTO v_rec FROM recovery_tokens WHERE token = p_token AND usado = false AND expira_at > now();\n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, NULL::text;\n    RETURN;\n  END IF;\n  SELECT u.email INTO v_email FROM usuarios u WHERE u.id = v_rec.usuario_id;\n  RETURN QUERY SELECT true, v_email;\nEND;\n$$;\n\n-- reset_password: pública (usa token)\nCREATE OR REPLACE FUNCTION reset_password(p_token text, p_nueva_password text)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public'\nAS $$\nDECLARE\n  v_rec recovery_tokens%ROWTYPE;\nBEGIN\n  SELECT * INTO v_rec FROM recovery_tokens WHERE token = p_token AND usado = false AND expira_at > now();\n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, 'Token inválido o expirado'::text;\n    RETURN;\n  END IF;\n  IF length(p_nueva_password) < 4 THEN\n    RETURN QUERY SELECT false, 'La contraseña debe tener al menos 4 caracteres'::text;\n    RETURN;\n  END IF;\n  UPDATE usuarios SET password_hash = crypt(p_nueva_password, gen_salt('bf')) WHERE id = v_rec.usuario_id;\n  UPDATE recovery_tokens SET usado = true WHERE id = v_rec.id;\n  RETURN QUERY SELECT true, 'Contraseña actualizada'::text;\nEND;\n$$;\n\n-- reset_password_admin: proteger con validación de admin\nCREATE OR REPLACE FUNCTION reset_password_admin(p_admin_id integer, p_usuario_id integer, p_password_nueva text)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public'\nAS $$\nBEGIN\n  -- Verificar que el que llama es admin\n  IF NOT EXISTS (SELECT 1 FROM usuarios WHERE id = p_admin_id AND rol = 'admin' AND activo = true) THEN\n    RETURN QUERY SELECT false, 'Solo administradores pueden resetear contraseñas'::text;\n    RETURN;\n  END IF;\n  IF length(p_password_nueva) < 4 THEN\n    RETURN QUERY SELECT false, 'La contraseña debe tener al menos 4 caracteres'::text;\n    RETURN;\n  END IF;\n  UPDATE usuarios SET password_hash = crypt(p_password_nueva, gen_salt('bf')) WHERE id = p_usuario_id;\n  RETURN QUERY SELECT true, 'Contraseña reseteada'::text;\nEND;\n$$;\n\n-- ============================================================\n-- FIX 4: Revocar ejecución anon de funciones que NO deben\n-- ser accesibles sin contexto de usuario\n-- Solo dejamos públicas: login, generar_recovery, validar_token, reset_password\n-- ============================================================\n\n-- Estas SÍ necesitan anon (pre-login):\n-- login, generar_recovery, validar_token, reset_password, get_permisos, cambiar_password\n-- (get_permisos y cambiar_password necesitan user_id que solo se obtiene post-login)\n\n-- Estas NO deben ser anon:\nREVOKE EXECUTE ON FUNCTION crear_usuario(text,text,text,text,text) FROM anon;\nREVOKE EXECUTE ON FUNCTION reset_password_admin(integer,integer,text) FROM anon;\n\n-- ============================================================\n-- FIX 5: Crear funciones seguras para lectura de datos\n-- que validen internamente que el caller sea admin\n-- (reemplazan el acceso directo a tablas)\n-- ============================================================\n\n-- Listar usuarios (solo admin)\nCREATE OR REPLACE FUNCTION listar_usuarios(p_admin_id integer)\nRETURNS TABLE (id integer, email text, nombre text, apellido text, rol text, activo boolean, ultimo_acceso timestamptz, created_at timestamptz)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public'\nAS $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM usuarios WHERE usuarios.id = p_admin_id AND usuarios.rol = 'admin' AND usuarios.activo = true) THEN\n    RAISE EXCEPTION 'Acceso denegado';\n  END IF;\n  RETURN QUERY SELECT u.id, u.email, u.nombre, u.apellido, u.rol, u.activo, u.ultimo_acceso, u.created_at FROM usuarios u ORDER BY u.created_at DESC;\nEND;\n$$;\n\nREVOKE EXECUTE ON FUNCTION listar_usuarios(integer) FROM anon;\n\n-- Actualizar usuario (solo admin)\nCREATE OR REPLACE FUNCTION actualizar_usuario(p_admin_id integer, p_usuario_id integer, p_campo text, p_valor text)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public'\nAS $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM usuarios WHERE id = p_admin_id AND rol = 'admin' AND activo = true) THEN\n    RETURN QUERY SELECT false, 'Acceso denegado'::text;\n    RETURN;\n  END IF;\n  IF p_admin_id = p_usuario_id AND p_campo = 'activo' THEN\n    RETURN QUERY SELECT false, 'No podés desactivarte a vos mismo'::text;\n    RETURN;\n  END IF;\n  CASE p_campo\n    WHEN 'rol' THEN UPDATE usuarios SET rol = p_valor WHERE id = p_usuario_id;\n    WHEN 'activo' THEN UPDATE usuarios SET activo = (p_valor = 'true') WHERE id = p_usuario_id;\n    ELSE RETURN QUERY SELECT false, 'Campo no permitido'::text; RETURN;\n  END CASE;\n  RETURN QUERY SELECT true, 'Actualizado'::text;\nEND;\n$$;\n\nREVOKE EXECUTE ON FUNCTION actualizar_usuario(integer,integer,text,text) FROM anon;\n\n-- Guardar permisos de un usuario (solo admin)\nCREATE OR REPLACE FUNCTION guardar_permisos(p_admin_id integer, p_usuario_id integer, p_permisos jsonb)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public'\nAS $$\nDECLARE\n  perm jsonb;\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM usuarios WHERE id = p_admin_id AND rol = 'admin' AND activo = true) THEN\n    RETURN QUERY SELECT false, 'Acceso denegado'::text;\n    RETURN;\n  END IF;\n  -- Borrar permisos actuales\n  DELETE FROM permisos_tarea WHERE usuario_id = p_usuario_id;\n  -- Insertar nuevos\n  FOR perm IN SELECT * FROM jsonb_array_elements(p_permisos)\n  LOOP\n    INSERT INTO permisos_tarea (usuario_id, agente, tarea, puede_ver, puede_editar)\n    VALUES (p_usuario_id, perm->>'agente', perm->>'tarea', (perm->>'puede_ver')::boolean, (perm->>'puede_editar')::boolean);\n  END LOOP;\n  RETURN QUERY SELECT true, 'Permisos actualizados'::text;\nEND;\n$$;\n\nREVOKE EXECUTE ON FUNCTION guardar_permisos(integer,integer,jsonb) FROM anon;\n\nNOTIFY pgrst, 'reload schema';\n"}	fix_all_security_issues	exxocet@hotmail.com	\N	\N
20260623160521	{"ALTER TABLE alcla_pacientes ADD COLUMN IF NOT EXISTS plan text;"}	add_plan_to_pacientes	exxocet@hotmail.com	\N	\N
20260502145955	{"\n-- Revocar anon de funciones que no deben ser pre-login\n-- (estas validan admin internamente, pero igual mejor no exponerlas a anon)\nREVOKE EXECUTE ON FUNCTION crear_usuario FROM anon;\nREVOKE EXECUTE ON FUNCTION listar_usuarios FROM anon;\nREVOKE EXECUTE ON FUNCTION actualizar_usuario FROM anon;\nREVOKE EXECUTE ON FUNCTION guardar_permisos FROM anon;\nREVOKE EXECUTE ON FUNCTION reset_password_admin FROM anon;\n\nNOTIFY pgrst, 'reload schema';\n"}	revoke_anon_admin_functions	exxocet@hotmail.com	\N	\N
20260502153854	{"\n-- Fix search_path: 'public,extensions' sin espacio\n\nCREATE OR REPLACE FUNCTION login(p_email text, p_password text)\nRETURNS TABLE (ok boolean, user_id integer, email text, nombre text, apellido text, rol text, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,extensions\nAS $$\nDECLARE v_user usuarios%ROWTYPE;\nBEGIN\n  SELECT * INTO v_user FROM usuarios u WHERE u.email = p_email;\n  IF NOT FOUND THEN RETURN QUERY SELECT false,NULL::integer,NULL::text,NULL::text,NULL::text,NULL::text,'Email o contraseña incorrectos'::text; RETURN; END IF;\n  IF NOT v_user.activo THEN RETURN QUERY SELECT false,NULL::integer,NULL::text,NULL::text,NULL::text,NULL::text,'Cuenta desactivada'::text; RETURN; END IF;\n  IF v_user.password_hash != crypt(p_password, v_user.password_hash) THEN RETURN QUERY SELECT false,NULL::integer,NULL::text,NULL::text,NULL::text,NULL::text,'Email o contraseña incorrectos'::text; RETURN; END IF;\n  UPDATE usuarios SET ultimo_acceso = now() WHERE id = v_user.id;\n  RETURN QUERY SELECT true,v_user.id,v_user.email,v_user.nombre,v_user.apellido,v_user.rol,'OK'::text;\nEND; $$;\n\nCREATE OR REPLACE FUNCTION cambiar_password(p_usuario_id integer, p_password_actual text, p_password_nueva text)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,extensions\nAS $$\nDECLARE v_hash text;\nBEGIN\n  SELECT password_hash INTO v_hash FROM usuarios WHERE id = p_usuario_id;\n  IF NOT FOUND THEN RETURN QUERY SELECT false,'Usuario no encontrado'::text; RETURN; END IF;\n  IF v_hash != crypt(p_password_actual, v_hash) THEN RETURN QUERY SELECT false,'Contraseña actual incorrecta'::text; RETURN; END IF;\n  IF length(p_password_nueva) < 4 THEN RETURN QUERY SELECT false,'Mínimo 4 caracteres'::text; RETURN; END IF;\n  UPDATE usuarios SET password_hash = crypt(p_password_nueva, gen_salt('bf')) WHERE id = p_usuario_id;\n  RETURN QUERY SELECT true,'Contraseña actualizada'::text;\nEND; $$;\n\nCREATE OR REPLACE FUNCTION crear_usuario(p_email text, p_password text, p_nombre text, p_apellido text, p_rol text)\nRETURNS TABLE (ok boolean, user_id integer, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,extensions\nAS $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM usuarios WHERE email = p_email) THEN RETURN QUERY SELECT false,NULL::integer,'Ya existe un usuario con ese email'::text; RETURN; END IF;\n  IF length(p_password) < 4 THEN RETURN QUERY SELECT false,NULL::integer,'Mínimo 4 caracteres'::text; RETURN; END IF;\n  INSERT INTO usuarios (email, password_hash, nombre, apellido, rol) VALUES (p_email, crypt(p_password, gen_salt('bf')), p_nombre, p_apellido, p_rol);\n  RETURN QUERY SELECT true,currval('usuarios_id_seq')::integer,'Usuario creado'::text;\nEND; $$;\n\nCREATE OR REPLACE FUNCTION generar_recovery(p_email text)\nRETURNS TABLE (ok boolean, token text, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,extensions\nAS $$\nDECLARE v_user_id integer; v_token text;\nBEGIN\n  SELECT id INTO v_user_id FROM usuarios WHERE email = p_email AND activo = true;\n  IF NOT FOUND THEN RETURN QUERY SELECT true,NULL::text,'Si el email existe, se generó un enlace'::text; RETURN; END IF;\n  UPDATE recovery_tokens SET usado = true WHERE usuario_id = v_user_id AND usado = false;\n  v_token := encode(gen_random_bytes(32), 'hex');\n  INSERT INTO recovery_tokens (usuario_id, token, expira_at) VALUES (v_user_id, v_token, now() + interval '1 hour');\n  RETURN QUERY SELECT true,v_token,'Token generado'::text;\nEND; $$;\n\nCREATE OR REPLACE FUNCTION reset_password(p_token text, p_nueva_password text)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,extensions\nAS $$\nDECLARE v_rec recovery_tokens%ROWTYPE;\nBEGIN\n  SELECT * INTO v_rec FROM recovery_tokens WHERE token = p_token AND usado = false AND expira_at > now();\n  IF NOT FOUND THEN RETURN QUERY SELECT false,'Token inválido o expirado'::text; RETURN; END IF;\n  IF length(p_nueva_password) < 4 THEN RETURN QUERY SELECT false,'Mínimo 4 caracteres'::text; RETURN; END IF;\n  UPDATE usuarios SET password_hash = crypt(p_nueva_password, gen_salt('bf')) WHERE id = v_rec.usuario_id;\n  UPDATE recovery_tokens SET usado = true WHERE id = v_rec.id;\n  RETURN QUERY SELECT true,'Contraseña actualizada'::text;\nEND; $$;\n\nCREATE OR REPLACE FUNCTION reset_password_admin(p_admin_id integer, p_usuario_id integer, p_password_nueva text)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,extensions\nAS $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM usuarios WHERE id = p_admin_id AND rol = 'admin' AND activo = true) THEN RETURN QUERY SELECT false,'Acceso denegado'::text; RETURN; END IF;\n  IF length(p_password_nueva) < 4 THEN RETURN QUERY SELECT false,'Mínimo 4 caracteres'::text; RETURN; END IF;\n  UPDATE usuarios SET password_hash = crypt(p_password_nueva, gen_salt('bf')) WHERE id = p_usuario_id;\n  RETURN QUERY SELECT true,'Contraseña reseteada'::text;\nEND; $$;\n\nCREATE OR REPLACE FUNCTION validar_token(p_token text)\nRETURNS TABLE (ok boolean, email text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO public,extensions\nAS $$\nDECLARE v_rec recovery_tokens%ROWTYPE; v_email text;\nBEGIN\n  SELECT * INTO v_rec FROM recovery_tokens WHERE token = p_token AND usado = false AND expira_at > now();\n  IF NOT FOUND THEN RETURN QUERY SELECT false,NULL::text; RETURN; END IF;\n  SELECT u.email INTO v_email FROM usuarios u WHERE u.id = v_rec.usuario_id;\n  RETURN QUERY SELECT true,v_email;\nEND; $$;\n\nCREATE OR REPLACE FUNCTION get_permisos(p_usuario_id integer)\nRETURNS TABLE (agente text, tarea text, puede_ver boolean, puede_editar boolean)\nLANGUAGE sql SECURITY DEFINER SET search_path TO public\nAS $$ SELECT pt.agente,pt.tarea,pt.puede_ver,pt.puede_editar FROM permisos_tarea pt WHERE pt.usuario_id = p_usuario_id; $$;\n\nCREATE OR REPLACE FUNCTION listar_usuarios(p_admin_id integer)\nRETURNS TABLE (id integer, email text, nombre text, apellido text, rol text, activo boolean, ultimo_acceso timestamptz, created_at timestamptz)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO public\nAS $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM usuarios WHERE usuarios.id = p_admin_id AND usuarios.rol = 'admin' AND usuarios.activo = true) THEN RAISE EXCEPTION 'Acceso denegado'; END IF;\n  RETURN QUERY SELECT u.id,u.email,u.nombre,u.apellido,u.rol,u.activo,u.ultimo_acceso,u.created_at FROM usuarios u ORDER BY u.created_at DESC;\nEND; $$;\n\nCREATE OR REPLACE FUNCTION actualizar_usuario(p_admin_id integer, p_usuario_id integer, p_campo text, p_valor text)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO public\nAS $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM usuarios WHERE id = p_admin_id AND rol = 'admin' AND activo = true) THEN RETURN QUERY SELECT false,'Acceso denegado'::text; RETURN; END IF;\n  IF p_admin_id = p_usuario_id AND p_campo = 'activo' THEN RETURN QUERY SELECT false,'No podés desactivarte a vos mismo'::text; RETURN; END IF;\n  CASE p_campo\n    WHEN 'rol' THEN UPDATE usuarios SET rol = p_valor WHERE id = p_usuario_id;\n    WHEN 'activo' THEN UPDATE usuarios SET activo = (p_valor = 'true') WHERE id = p_usuario_id;\n    ELSE RETURN QUERY SELECT false,'Campo no permitido'::text; RETURN;\n  END CASE;\n  RETURN QUERY SELECT true,'Actualizado'::text;\nEND; $$;\n\nCREATE OR REPLACE FUNCTION guardar_permisos(p_admin_id integer, p_usuario_id integer, p_permisos jsonb)\nRETURNS TABLE (ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO public\nAS $$\nDECLARE perm jsonb;\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM usuarios WHERE id = p_admin_id AND rol = 'admin' AND activo = true) THEN RETURN QUERY SELECT false,'Acceso denegado'::text; RETURN; END IF;\n  DELETE FROM permisos_tarea WHERE usuario_id = p_usuario_id;\n  FOR perm IN SELECT * FROM jsonb_array_elements(p_permisos) LOOP\n    INSERT INTO permisos_tarea (usuario_id, agente, tarea, puede_ver, puede_editar)\n    VALUES (p_usuario_id, perm->>'agente', perm->>'tarea', (perm->>'puede_ver')::boolean, (perm->>'puede_editar')::boolean);\n  END LOOP;\n  RETURN QUERY SELECT true,'Permisos actualizados'::text;\nEND; $$;\n"}	fix_search_path_v2	exxocet@hotmail.com	\N	\N
20260514162645	{"\n-- ─── 1. sessions ────────────────────────────────\n-- Estado transitorio de cada conversación activa.\n-- Reemplaza Redis. Limpiar con cron donde expires_at < now()\n\nCREATE TABLE IF NOT EXISTS sessions (\n  telefono       text PRIMARY KEY,\n  cliente_id     text NOT NULL,\n  estado         text NOT NULL DEFAULT 'greeting',\n  data           jsonb DEFAULT '{}'::jsonb,\n  bot_pausado    boolean DEFAULT false,\n  expires_at     timestamptz DEFAULT (now() + interval '24 hours'),\n  created_at     timestamptz DEFAULT now(),\n  updated_at     timestamptz DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_sessions_expires    ON sessions(expires_at);\nCREATE INDEX IF NOT EXISTS idx_sessions_cliente_id ON sessions(cliente_id);\n\n-- Auto-update updated_at\nCREATE OR REPLACE FUNCTION update_sessions_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_sessions_updated_at ON sessions;\nCREATE TRIGGER trg_sessions_updated_at\n  BEFORE UPDATE ON sessions\n  FOR EACH ROW EXECUTE FUNCTION update_sessions_updated_at();\n\nALTER TABLE sessions ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"sessions_tenant_isolation\\" ON sessions\n  FOR ALL USING (cliente_id = current_setting('app.cliente_id', true));\n"}	cig_sessions	exxocet@hotmail.com	\N	\N
20260514162656	{"\n-- ─── 2. turnos ──────────────────────────────────\n-- Registro final del turno. Esta tabla la lee el panel.\n\nCREATE TABLE IF NOT EXISTS turnos (\n  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  cliente_id        text NOT NULL,\n  telefono          text NOT NULL,\n  nombre            text NOT NULL,\n  es_paciente       boolean,\n  especialidad      text,\n  cobertura         text,          -- particular | prepaga | obra_social\n  cobertura_detalle text,\n  fecha_pref        text,\n  fecha_especifica  text,\n  pregunta_extra    text,\n  estado            text DEFAULT 'pending',  -- pending | contacted | scheduled | cancelled\n  nota_interna      text,\n  created_at        timestamptz DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_turnos_cliente_estado ON turnos(cliente_id, estado);\nCREATE INDEX IF NOT EXISTS idx_turnos_telefono        ON turnos(telefono);\nCREATE INDEX IF NOT EXISTS idx_turnos_created_at      ON turnos(created_at DESC);\n\nALTER TABLE turnos ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"turnos_tenant_isolation\\" ON turnos\n  FOR ALL USING (cliente_id = current_setting('app.cliente_id', true));\n"}	cig_turnos	exxocet@hotmail.com	\N	\N
20260514162705	{"\n-- ─── 3. messages ────────────────────────────────\n-- Historial completo de mensajes (para inbox del panel V3).\n\nCREATE TABLE IF NOT EXISTS messages (\n  id           bigserial PRIMARY KEY,\n  cliente_id   text NOT NULL,\n  telefono     text NOT NULL,\n  direction    text NOT NULL CHECK (direction IN ('in','out')),\n  sender       text NOT NULL CHECK (sender IN ('paciente','bot','coordinador')),\n  body         text,\n  message_type text DEFAULT 'text' CHECK (message_type IN ('text','interactive','template')),\n  meta         jsonb,\n  created_at   timestamptz DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_messages_telefono   ON messages(telefono, created_at);\nCREATE INDEX IF NOT EXISTS idx_messages_cliente_id ON messages(cliente_id, created_at DESC);\n\nALTER TABLE messages ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"messages_tenant_isolation\\" ON messages\n  FOR ALL USING (cliente_id = current_setting('app.cliente_id', true));\n"}	cig_messages	exxocet@hotmail.com	\N	\N
20260514162714	{"\n-- Habilitar Realtime en las tablas que necesita el panel\nALTER PUBLICATION supabase_realtime ADD TABLE turnos;\nALTER PUBLICATION supabase_realtime ADD TABLE messages;\nALTER PUBLICATION supabase_realtime ADD TABLE sessions;\n"}	cig_realtime_publications	exxocet@hotmail.com	\N	\N
20260514162723	{"\n-- Habilitar extensión pg_cron (viene disponible en Supabase)\nCREATE EXTENSION IF NOT EXISTS pg_cron;\n\n-- Cron: limpiar sesiones expiradas cada hora\nSELECT cron.schedule(\n  'cig-cleanup-sessions',\n  '0 * * * *',\n  $$DELETE FROM sessions WHERE expires_at < now()$$\n);\n"}	cig_cleanup_cron	exxocet@hotmail.com	\N	\N
20260516205754	{"\nCREATE TABLE IF NOT EXISTS kiosco_clientes (\n  id           text PRIMARY KEY,          -- ej: KSC-001\n  nombre       text NOT NULL,\n  direccion    text,\n  zona         text,\n  telefono     text,                      -- referencial, no es clave\n  activo       boolean DEFAULT true,\n  created_at   timestamptz DEFAULT now()\n);\n\n-- Datos de ejemplo\nINSERT INTO kiosco_clientes (id, nombre, direccion, zona) VALUES\n  ('KSC-001', 'Kiosco El Sol',       'Av. Corrientes 1234, CABA',  'Centro'),\n  ('KSC-002', 'Kiosco La Esquina',   'Rivadavia 567, Flores',      'Oeste'),\n  ('KSC-003', 'Kiosco Don Pepe',     'Cabildo 890, Belgrano',      'Norte'),\n  ('KSC-004', 'Kiosco Los Amigos',   'San Martín 321, Palermo',    'Norte'),\n  ('KSC-005', 'Kiosco El Barrio',    'Mitre 456, Boedo',           'Sur')\nON CONFLICT (id) DO NOTHING;\n"}	kiosco_clientes	exxocet@hotmail.com	\N	\N
20260516205806	{"\nCREATE TABLE IF NOT EXISTS kiosco_pedidos (\n  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  numero_orden    text UNIQUE,              -- KSC-001-00042\n  cliente_id      text NOT NULL,            -- 'kiosco'\n  kiosco_id       text NOT NULL REFERENCES kiosco_clientes(id),\n  telefono        text NOT NULL,\n  estado          text DEFAULT 'pendiente', -- pendiente | confirmado | preparando | enviado | entregado | cancelado\n  total_items     int DEFAULT 0,\n  nota            text,\n  created_at      timestamptz DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_kiosco_pedidos_kiosco  ON kiosco_pedidos(kiosco_id);\nCREATE INDEX IF NOT EXISTS idx_kiosco_pedidos_estado  ON kiosco_pedidos(estado);\nCREATE INDEX IF NOT EXISTS idx_kiosco_pedidos_created ON kiosco_pedidos(created_at DESC);\n\n-- Secuencia para número de orden por kiosco\nCREATE SEQUENCE IF NOT EXISTS kiosco_orden_seq START 1;\n\n-- Función para generar número de orden\nCREATE OR REPLACE FUNCTION generar_numero_orden(p_kiosco_id text)\nRETURNS text AS $$\nDECLARE\n  v_num int;\nBEGIN\n  SELECT nextval('kiosco_orden_seq') INTO v_num;\n  RETURN p_kiosco_id || '-' || LPAD(v_num::text, 5, '0');\nEND;\n$$ LANGUAGE plpgsql;\n\nALTER TABLE kiosco_pedidos ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"kiosco_pedidos_open\\" ON kiosco_pedidos FOR ALL USING (true) WITH CHECK (true);\n"}	kiosco_pedidos	exxocet@hotmail.com	\N	\N
20260623162900	{"\nCREATE POLICY \\"alcla_pacientes_update_anon\\" ON alcla_pacientes FOR UPDATE USING (true) WITH CHECK (true);\n"}	add_update_policy_alcla_pacientes	exxocet@hotmail.com	\N	\N
