20260516205816	{"\nCREATE TABLE IF NOT EXISTS kiosco_pedido_items (\n  id          bigserial PRIMARY KEY,\n  pedido_id   uuid NOT NULL REFERENCES kiosco_pedidos(id) ON DELETE CASCADE,\n  producto_id text NOT NULL,\n  nombre      text NOT NULL,\n  categoria   text NOT NULL,\n  cantidad    int NOT NULL DEFAULT 1,\n  precio_unit numeric(10,2),\n  subtotal    numeric(10,2),\n  created_at  timestamptz DEFAULT now()\n);\n\nCREATE INDEX IF NOT EXISTS idx_kiosco_items_pedido ON kiosco_pedido_items(pedido_id);\n\nALTER TABLE kiosco_pedido_items ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \\"kiosco_items_open\\" ON kiosco_pedido_items FOR ALL USING (true) WITH CHECK (true);\n\n-- Realtime para el panel\nALTER PUBLICATION supabase_realtime ADD TABLE kiosco_pedidos;\nALTER PUBLICATION supabase_realtime ADD TABLE kiosco_pedido_items;\n"}	kiosco_pedido_items	exxocet@hotmail.com	\N	\N
20260521154421	{"\n-- Agrega la columna handoff_pending a public.sessions\nALTER TABLE public.sessions\n  ADD COLUMN IF NOT EXISTS handoff_pending boolean NOT NULL DEFAULT false;\n\n-- Índice para que el Realtime filter y las queries sean rápidas\nCREATE INDEX IF NOT EXISTS idx_sessions_handoff_pending\n  ON public.sessions (cliente_id, handoff_pending)\n  WHERE handoff_pending = true;\n\n-- Comentario descriptivo\nCOMMENT ON COLUMN public.sessions.handoff_pending IS\n  'true cuando el paciente solicitó hablar con una persona. El panel lo usa para mostrar la alerta de atención urgente.';\n"}	add_handoff_pending_to_sessions	exxocet@hotmail.com	\N	\N
20260528040811	{"\n-- =============================================\n-- ALCLA: Pacientes\n-- =============================================\nCREATE TABLE public.alcla_pacientes (\n  id            serial PRIMARY KEY,\n  nombre        text NOT NULL,\n  apellido      text NOT NULL,\n  dni           text NOT NULL UNIQUE,\n  telefono      text,\n  email         text,\n  cobertura     text,\n  nro_socio     text,\n  created_at    timestamptz DEFAULT now()\n);\n\n-- =============================================\n-- ALCLA: Tratamientos (agrupador de sesiones)\n-- =============================================\nCREATE TABLE public.alcla_tratamientos (\n  id              serial PRIMARY KEY,\n  paciente_id     int NOT NULL REFERENCES public.alcla_pacientes(id) ON DELETE CASCADE,\n  especialidad    text NOT NULL, -- Kinesiología | T. Ocupacional | Fonoaudiología | Neuropsicología | Fisiatría\n  modulo          text,          -- Ej: \\"Mod. ambulatorio simple\\"\n  sesiones_total  int NOT NULL DEFAULT 1,\n  estado          text NOT NULL DEFAULT 'activo', -- activo | finalizado | suspendido\n  created_at      timestamptz DEFAULT now()\n);\n\n-- =============================================\n-- ALCLA: Sesiones / Turnos individuales\n-- =============================================\nCREATE TABLE public.alcla_sesiones (\n  id              serial PRIMARY KEY,\n  tratamiento_id  int NOT NULL REFERENCES public.alcla_tratamientos(id) ON DELETE CASCADE,\n  paciente_id     int NOT NULL REFERENCES public.alcla_pacientes(id) ON DELETE CASCADE,\n  fecha           date NOT NULL,\n  hora            time NOT NULL,\n  turno           text NOT NULL,     -- TM | TT\n  box             text NOT NULL,     -- K1..K12, T1..T6, F1, F2, N1, Fi\n  especialidad    text NOT NULL,\n  piso            text NOT NULL,     -- 1° | 2°\n  profesional     text,              -- Profesional 1, 2, etc.\n  sesion_nro      int,               -- N° de sesión dentro del tratamiento\n  estado          text NOT NULL DEFAULT 'confirmado', -- confirmado | ausente | reprogramado | cancelado\n  nota            text,\n  created_at      timestamptz DEFAULT now(),\n  UNIQUE (fecha, hora, box)          -- evita doble-booking en el mismo box/horario\n);\n\n-- Índices útiles para búsquedas frecuentes\nCREATE INDEX idx_alcla_pacientes_dni     ON public.alcla_pacientes(dni);\nCREATE INDEX idx_alcla_pacientes_nombre  ON public.alcla_pacientes(apellido, nombre);\nCREATE INDEX idx_alcla_sesiones_fecha    ON public.alcla_sesiones(fecha);\nCREATE INDEX idx_alcla_sesiones_paciente ON public.alcla_sesiones(paciente_id);\n\n-- RLS habilitado (sin políticas permisivas = acceso solo desde service_role / server)\nALTER TABLE public.alcla_pacientes   ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.alcla_tratamientos ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.alcla_sesiones    ENABLE ROW LEVEL SECURITY;\n\n-- Políticas: acceso total para usuarios autenticados de la app\nCREATE POLICY \\"alcla_pacientes_all\\"    ON public.alcla_pacientes    FOR ALL TO authenticated USING (true) WITH CHECK (true);\nCREATE POLICY \\"alcla_tratamientos_all\\" ON public.alcla_tratamientos FOR ALL TO authenticated USING (true) WITH CHECK (true);\nCREATE POLICY \\"alcla_sesiones_all\\"     ON public.alcla_sesiones     FOR ALL TO authenticated USING (true) WITH CHECK (true);\n\n-- Acceso anon de sólo lectura para que el frontend HTML pueda consultar sin login\n-- (Si preferís requerir auth en el futuro, estas dos líneas se eliminan)\nCREATE POLICY \\"alcla_pacientes_read_anon\\"   ON public.alcla_pacientes    FOR SELECT TO anon USING (true);\nCREATE POLICY \\"alcla_tratamientos_read_anon\\" ON public.alcla_tratamientos FOR SELECT TO anon USING (true);\nCREATE POLICY \\"alcla_sesiones_read_anon\\"    ON public.alcla_sesiones     FOR SELECT TO anon USING (true);\n\nCREATE POLICY \\"alcla_pacientes_write_anon\\"   ON public.alcla_pacientes    FOR INSERT TO anon WITH CHECK (true);\nCREATE POLICY \\"alcla_tratamientos_write_anon\\" ON public.alcla_tratamientos FOR INSERT TO anon WITH CHECK (true);\nCREATE POLICY \\"alcla_sesiones_write_anon\\"    ON public.alcla_sesiones     FOR INSERT TO anon WITH CHECK (true);\n"}	alcla_create_pacientes_tratamientos_sesiones	exxocet@hotmail.com	\N	\N
20260602154644	{"\n-- 1. Eliminar la PK actual (solo telefono)\nALTER TABLE public.sessions DROP CONSTRAINT sessions_pkey;\n\n-- 2. Crear la nueva PK compuesta (telefono + cliente_id)\nALTER TABLE public.sessions ADD CONSTRAINT sessions_pkey PRIMARY KEY (telefono, cliente_id);\n"}	sessions_pk_telefono_cliente_id	exxocet@hotmail.com	\N	\N
20260605224405	{"\nCREATE TABLE public.alcla_profesionales (\n  id        serial PRIMARY KEY,\n  nombre    text NOT NULL,\n  apellido  text,\n  especialidad text,\n  matricula text,\n  activo    boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.alcla_profesionales ENABLE ROW LEVEL SECURITY;\n\n-- Política: lectura pública con anon key (igual que alcla_pacientes/sesiones)\nCREATE POLICY \\"anon_select\\" ON public.alcla_profesionales\n  FOR SELECT USING (true);\n\n-- Política: inserción/actualización/borrado solo con service key o anon (para la app)\nCREATE POLICY \\"anon_insert\\" ON public.alcla_profesionales\n  FOR INSERT WITH CHECK (true);\n\nCREATE POLICY \\"anon_update\\" ON public.alcla_profesionales\n  FOR UPDATE USING (true);\n\nCREATE POLICY \\"anon_delete\\" ON public.alcla_profesionales\n  FOR DELETE USING (true);\n"}	create_alcla_profesionales	exxocet@hotmail.com	\N	\N
