20260605225617	{"\nDROP FUNCTION IF EXISTS public.listar_usuarios(integer);\n\nCREATE FUNCTION public.listar_usuarios(p_admin_id integer)\nRETURNS TABLE(\n  id integer, email text, nombre text, apellido text, rol text,\n  activo boolean, ver_estadisticas boolean, ver_profesionales boolean,\n  ultimo_acceso timestamptz, created_at timestamptz\n)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'\nAS $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM usuarios WHERE usuarios.id = p_admin_id AND usuarios.rol = 'admin' AND usuarios.activo = true\n  ) THEN RAISE EXCEPTION 'Acceso denegado'; END IF;\n  RETURN QUERY\n    SELECT u.id, u.email, u.nombre, u.apellido, u.rol, u.activo,\n           u.ver_estadisticas, u.ver_profesionales, u.ultimo_acceso, u.created_at\n    FROM usuarios u ORDER BY u.created_at DESC;\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.actualizar_usuario(\n  p_admin_id integer, p_usuario_id integer, p_campo text, p_valor text\n)\nRETURNS TABLE(ok boolean, mensaje text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'\nAS $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM usuarios WHERE id = p_admin_id AND rol = 'admin' AND activo = true\n  ) THEN RETURN QUERY SELECT false, 'Acceso denegado'::text; RETURN; END IF;\n\n  IF p_admin_id = p_usuario_id AND p_campo = 'activo' AND p_valor = 'false' THEN\n    RETURN QUERY SELECT false, 'No podés desactivarte a vos mismo'::text; RETURN;\n  END IF;\n\n  CASE p_campo\n    WHEN 'rol'               THEN UPDATE usuarios SET rol = p_valor WHERE id = p_usuario_id;\n    WHEN 'activo'            THEN UPDATE usuarios SET activo = (p_valor = 'true') WHERE id = p_usuario_id;\n    WHEN 'nombre'            THEN UPDATE usuarios SET nombre = p_valor WHERE id = p_usuario_id;\n    WHEN 'apellido'          THEN UPDATE usuarios SET apellido = p_valor WHERE id = p_usuario_id;\n    WHEN 'email'             THEN UPDATE usuarios SET email = p_valor WHERE id = p_usuario_id;\n    WHEN 'ver_estadisticas'  THEN UPDATE usuarios SET ver_estadisticas = (p_valor = 'true') WHERE id = p_usuario_id;\n    WHEN 'ver_profesionales' THEN UPDATE usuarios SET ver_profesionales = (p_valor = 'true') WHERE id = p_usuario_id;\n    WHEN 'password'          THEN UPDATE usuarios SET password_hash = crypt(p_valor, gen_salt('bf')) WHERE id = p_usuario_id;\n    ELSE RETURN QUERY SELECT false, 'Campo no permitido: ' || p_campo; RETURN;\n  END CASE;\n\n  RETURN QUERY SELECT true, 'Actualizado'::text;\nEND;\n$$;\n"}	drop_and_recreate_usuario_functions	exxocet@hotmail.com	\N	\N
