20260608004842	{"\nCREATE TABLE IF NOT EXISTS alcla_stats_historicos (\n  id           serial PRIMARY KEY,\n  anio         int    NOT NULL,\n  mes          int    NOT NULL CHECK (mes BETWEEN 1 AND 12),\n  especialidad text   NOT NULL,\n  ocupados     int    NOT NULL DEFAULT 0,\n  disponibles  int    NOT NULL,\n  UNIQUE (anio, mes, especialidad)\n);\n\nALTER TABLE alcla_stats_historicos ENABLE ROW LEVEL SECURITY;\n\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_policies\n    WHERE tablename = 'alcla_stats_historicos' AND policyname = 'lectura publica'\n  ) THEN\n    CREATE POLICY \\"lectura publica\\" ON alcla_stats_historicos\n      FOR SELECT USING (true);\n  END IF;\nEND $$;\n"}	create_alcla_stats_historicos	exxocet@hotmail.com	\N	\N
