20260610170921	{"\n-- Campo vencimiento de orden/autorización en pacientes\nALTER TABLE alcla_pacientes\n  ADD COLUMN IF NOT EXISTS vto_orden date;\n\n-- Campo sobreturno en sesiones\nALTER TABLE alcla_sesiones\n  ADD COLUMN IF NOT EXISTS sobreturno boolean NOT NULL DEFAULT false;\n\n-- Comentarios descriptivos\nCOMMENT ON COLUMN alcla_pacientes.vto_orden IS 'Fecha de vencimiento de la orden o autorización de la prepaga';\nCOMMENT ON COLUMN alcla_sesiones.sobreturno IS 'Indica si la sesión fue cargada manualmente como sobreturno (ocupa un slot ya ocupado)';\n"}	add_vto_orden_and_sobreturno	exxocet@hotmail.com	\N	\N
20260610211337	{"\n-- Eliminar la constraint UNIQUE simple\nALTER TABLE alcla_sesiones \n  DROP CONSTRAINT alcla_sesiones_fecha_hora_box_key;\n\n-- Reemplazar con índice único parcial:\n-- solo aplica cuando sobreturno = false (turnos normales no pueden duplicar fecha+hora+box)\n-- los sobreturnos (sobreturno = true) quedan libres de esta restricción\nCREATE UNIQUE INDEX alcla_sesiones_fecha_hora_box_normal_key\n  ON alcla_sesiones (fecha, hora, box)\n  WHERE sobreturno = false;\n"}	sobreturno_allow_duplicate_slots	exxocet@hotmail.com	\N	\N
