20260612193206	{"\nCREATE TABLE alcla_coberturas (\n  id      serial PRIMARY KEY,\n  nombre  text NOT NULL UNIQUE,\n  activo  boolean NOT NULL DEFAULT true\n);\n\nCREATE TABLE alcla_planes (\n  id           serial PRIMARY KEY,\n  cobertura_id integer NOT NULL REFERENCES alcla_coberturas(id) ON DELETE CASCADE,\n  nombre       text NOT NULL,\n  activo       boolean NOT NULL DEFAULT true,\n  UNIQUE(cobertura_id, nombre)\n);\n\n-- RLS: misma lógica que el resto de tablas alcla\nALTER TABLE alcla_coberturas ENABLE ROW LEVEL SECURITY;\nALTER TABLE alcla_planes     ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"alcla_coberturas_read\\" ON alcla_coberturas FOR SELECT USING (true);\nCREATE POLICY \\"alcla_planes_read\\"     ON alcla_planes     FOR SELECT USING (true);\nCREATE POLICY \\"alcla_coberturas_write\\" ON alcla_coberturas FOR ALL USING (true) WITH CHECK (true);\nCREATE POLICY \\"alcla_planes_write\\"     ON alcla_planes     FOR ALL USING (true) WITH CHECK (true);\n"}	create_coberturas_planes	exxocet@hotmail.com	\N	\N
20260617162238	{"\n-- 1. Nueva tabla padrón de pacientes CIG\nCREATE TABLE IF NOT EXISTS public.cig_pacientes (\n  nro_doc      text        NOT NULL,\n  tipo_doc     text        NOT NULL DEFAULT 'DNI',\n  apellido     text        NOT NULL DEFAULT '',\n  nombre       text        NOT NULL DEFAULT '',\n  fecha_nac    date        NULL,\n  created_at   timestamptz NOT NULL DEFAULT now(),\n  CONSTRAINT cig_pacientes_pkey PRIMARY KEY (nro_doc)\n);\n\n-- 2. Columnas nuevas en turnos\nALTER TABLE public.turnos\n  ADD COLUMN IF NOT EXISTS dni          text,\n  ADD COLUMN IF NOT EXISTS fecha_nac    date,\n  ADD COLUMN IF NOT EXISTS obra_social  text,\n  ADD COLUMN IF NOT EXISTS tipo         text;\n"}	cig_schema_v2	exxocet@hotmail.com	\N	\N
20260617214345	{"\n-- ── turnos: agregar columnas nuevas que faltan ────────────────\nALTER TABLE turnos\n  ADD COLUMN IF NOT EXISTS accion      text,      -- solicitud | reprogramacion | cancelacion\n  ADD COLUMN IF NOT EXISTS profesional text,      -- solo en reprog/cancel\n  ADD COLUMN IF NOT EXISTS preferencia text,      -- texto libre de día/horario\n  ADD COLUMN IF NOT EXISTS obra_social text;      -- duplicado en turno para no depender de paciente\n\n-- obra_social ya puede existir (la veo en el schema), el IF NOT EXISTS la protege\n\n-- ── sessions: agregar columna para el lookup de paciente ─────\nALTER TABLE sessions\n  ADD COLUMN IF NOT EXISTS paciente_encontrado boolean DEFAULT false;\n\n-- ── cig_pacientes: agregar obra_social y telefono ────────────\nALTER TABLE cig_pacientes\n  ADD COLUMN IF NOT EXISTS obra_social text,\n  ADD COLUMN IF NOT EXISTS telefono    text;\n\n-- ── índices útiles ────────────────────────────────────────────\nCREATE INDEX IF NOT EXISTS idx_cig_pacientes_nro_doc ON cig_pacientes(nro_doc);\nCREATE INDEX IF NOT EXISTS idx_turnos_accion         ON turnos(accion);\n"}	cig_v2_turnos_sessions	exxocet@hotmail.com	\N	\N
20260618163705	{"\n-- 3: Campo notas en alcla_sesiones\nALTER TABLE alcla_sesiones ADD COLUMN IF NOT EXISTS notas text;\n\n-- 2: Box \\"Otros\\" — agregar a alcla_especialidades si existe, sino solo documentar\n-- Los boxes van hardcodeados en el HTML (CS_BOXES), así que solo necesitamos\n-- que la columna especialidad pueda tener el valor 'Otros'\n-- No hay constraint que lo impida — alcla_sesiones.especialidad es text libre\n"}	add_notas_y_otros_especialidad	exxocet@hotmail.com	\N	\N
20260618235400	{"\n-- ═══════════════════════════════════════════════════════════\n--  ESTÉTICA JURI — Schema inicial\n-- ═══════════════════════════════════════════════════════════\n\n-- ── SESIONES ─────────────────────────────────────────────────────────\nCREATE TABLE juri_sesiones (\n  telefono        TEXT PRIMARY KEY,\n  estado          TEXT NOT NULL DEFAULT 'inicio',\n  data            JSONB NOT NULL DEFAULT '{}',\n  bot_pausado     BOOLEAN NOT NULL DEFAULT false,\n  handoff_pending BOOLEAN NOT NULL DEFAULT false,\n  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE INDEX juri_sesiones_updated ON juri_sesiones(updated_at);\n\n-- ── TURNOS ───────────────────────────────────────────────────────────\nCREATE SEQUENCE juri_turnos_seq START 1000;\n\nCREATE TABLE juri_turnos (\n  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  numero          TEXT NOT NULL DEFAULT ('#EJ' || LPAD(nextval('juri_turnos_seq')::TEXT, 4, '0')),\n  telefono        TEXT,\n  paciente_nombre TEXT,\n  solicitado_por  TEXT,\n  prepaga         TEXT,\n  tratamiento     TEXT,\n  sucursal        TEXT,\n  disponibilidad  TEXT,\n  estado          TEXT NOT NULL DEFAULT 'Pendiente',\n  nota_interna    TEXT,\n  origen          TEXT DEFAULT 'bot',\n  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE INDEX juri_turnos_estado   ON juri_turnos(estado);\nCREATE INDEX juri_turnos_sucursal ON juri_turnos(sucursal);\nCREATE INDEX juri_turnos_created  ON juri_turnos(created_at DESC);\n\n-- función para número legible (usada desde PHP también)\nCREATE OR REPLACE FUNCTION juri_next_numero()\nRETURNS TEXT LANGUAGE sql AS $$\n  SELECT '#EJ' || LPAD(nextval('juri_turnos_seq')::TEXT, 4, '0');\n$$;\n\n-- ── MENSAJES ─────────────────────────────────────────────────────────\nCREATE TABLE juri_mensajes (\n  id          BIGSERIAL PRIMARY KEY,\n  telefono    TEXT NOT NULL,\n  direction   TEXT NOT NULL CHECK (direction IN ('in','out')),\n  body        TEXT NOT NULL,\n  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE INDEX juri_mensajes_tel ON juri_mensajes(telefono, created_at DESC);\n\n-- ── USUARIOS PANEL ───────────────────────────────────────────────────\nCREATE TABLE juri_usuarios (\n  id         SERIAL PRIMARY KEY,\n  username   TEXT UNIQUE NOT NULL,\n  password   TEXT NOT NULL,\n  nombre     TEXT,\n  role       TEXT DEFAULT 'operador',\n  activo     BOOLEAN DEFAULT true,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Usuario admin inicial (password plain: juri2024 — cambiar en producción)\nINSERT INTO juri_usuarios (username, password, nombre, role)\nVALUES ('admin', 'juri2024', 'Administrador', 'admin');\n\n-- ── TRIGGER updated_at ───────────────────────────────────────────────\nCREATE OR REPLACE FUNCTION juri_update_updated_at()\nRETURNS TRIGGER LANGUAGE plpgsql AS $$\nBEGIN NEW.updated_at = now(); RETURN NEW; END;\n$$;\n\nCREATE TRIGGER juri_sesiones_updated\n  BEFORE UPDATE ON juri_sesiones\n  FOR EACH ROW EXECUTE FUNCTION juri_update_updated_at();\n\nCREATE TRIGGER juri_turnos_updated\n  BEFORE UPDATE ON juri_turnos\n  FOR EACH ROW EXECUTE FUNCTION juri_update_updated_at();\n\n-- ── RLS — abrir todo para service_role (el proxy PHP usa esa key) ─────\nALTER TABLE juri_sesiones  ENABLE ROW LEVEL SECURITY;\nALTER TABLE juri_turnos    ENABLE ROW LEVEL SECURITY;\nALTER TABLE juri_mensajes  ENABLE ROW LEVEL SECURITY;\nALTER TABLE juri_usuarios  ENABLE ROW LEVEL SECURITY;\n\n-- Políticas permisivas para service_role (bypass RLS by default en Supabase)\n-- Para acceso desde n8n con anon key, descomentar:\n-- CREATE POLICY \\"juri_anon_all_sesiones\\" ON juri_sesiones FOR ALL TO anon USING (true) WITH CHECK (true);\n-- CREATE POLICY \\"juri_anon_all_turnos\\"   ON juri_turnos   FOR ALL TO anon USING (true) WITH CHECK (true);\n-- CREATE POLICY \\"juri_anon_all_mensajes\\" ON juri_mensajes FOR ALL TO anon USING (true) WITH CHECK (true);\n"}	juri_initial_schema	exxocet@hotmail.com	\N	\N
20260619001600	{"\n-- Políticas para anon key (el proxy PHP usa anon key)\nCREATE POLICY \\"juri_anon_sesiones\\"  ON juri_sesiones  FOR ALL TO anon USING (true) WITH CHECK (true);\nCREATE POLICY \\"juri_anon_turnos\\"    ON juri_turnos    FOR ALL TO anon USING (true) WITH CHECK (true);\nCREATE POLICY \\"juri_anon_mensajes\\"  ON juri_mensajes  FOR ALL TO anon USING (true) WITH CHECK (true);\nCREATE POLICY \\"juri_anon_usuarios\\"  ON juri_usuarios  FOR ALL TO anon USING (true) WITH CHECK (true);\n"}	juri_rls_anon_policies	exxocet@hotmail.com	\N	\N
